function insertBlock(blocks: number[][], extra: number[]): number[][] {
  const all = [...blocks.map(b => [b[0], b[1]]), [extra[0], extra[1]]].sort((a, b) => a[0] - b[0]);
  const out: number[][] = [];
  for (const [s, e] of all) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}

