class Solution:
    def insertBlock(self, blocks: List[List[int]], extra: List[int]) -> List[List[int]]:
        out = []
        for s, e in sorted(blocks + [extra]):
            if out and s <= out[-1][1]:
                out[-1][1] = max(out[-1][1], e)
            else:
                out.append([s, e])
        return out

