function insertBlock(blocks: number[][], extra: number[]): number[][] {
  const out: number[][] = [];
  let [s, e] = extra, i = 0;
  while (i < blocks.length && blocks[i][1] < s) out.push(blocks[i++]);
  while (i < blocks.length && blocks[i][0] <= e) {
    s = Math.min(s, blocks[i][0]);
    e = Math.max(e, blocks[i][1]);
    i++;
  }
  out.push([s, e]);
  while (i < blocks.length) out.push(blocks[i++]);
  return out;
}

